import json
import time

URL = "https://lauwang.vn/dat-ban/"
BRANCH = "51A Hồ Tùng Mậu, HN"  # cơ sở như bản cũ

SEL_NAME = 'input[name="your-name"]'
SEL_PHONE = 'input[name="phone"]'
SEL_ADULT = 'input[name="adult"]'
SEL_DATE = 'input[name="date"]'
SEL_DATE_SELECT = 'select[name="date"]'
SEL_TIME = 'select[name="time"]'
SEL_ADDR = 'select[name="address"]'
SEL_EMAIL = 'input[name="email"], input[type="email"]'

DAY_STR, MON_STR, YEAR_STR = DATE_DMY.split("/")
DAY_TXT = str(int(DAY_STR))
MON_IDX = str(int(MON_STR) - 1)   # jQuery UI data-month là 0-based
YEAR_TXT = str(int(YEAR_STR))


def J(x):
    return json.dumps(x)


# Helper JS được nhúng vào MỖI lần gọi (không dựa vào window.* vì new_tab() làm mất biến cũ)
LIB = """
const fire = el => {
  el.dispatchEvent(new Event('input', {bubbles: true}));
  el.dispatchEvent(new Event('change', {bubbles: true}));
  el.dispatchEvent(new Event('blur', {bubbles: true}));
};
const setNative = (el, v) => {
  const proto = el.tagName === 'SELECT' ? HTMLSelectElement.prototype
              : el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype
              : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, v);
};
"""


def wait_until(expr, timeout=15.0, step=0.2):
    """Vòng lặp ngắn: thử tối đa `timeout` giây, mỗi lần cách `step` giây."""
    end = time.time() + timeout
    while time.time() < end:
        try:
            if js("!!(" + expr + ")"):
                return True
        except Exception:
            pass
        time.sleep(step)
    return False


def set_text(sel, text):
    code = ("(()=>{" + LIB +
            "const el=document.querySelector(" + J(sel) + ");"
            "if(!el)return null;"
            "el.scrollIntoView({block:'center'});el.focus();"
            "setNative(el," + J(text) + ");fire(el);"
            "return el.value;})()")
    return js(code)


def set_select(sel, wants):
    code = ("(()=>{" + LIB +
            "const el=document.querySelector(" + J(sel) + ");"
            "if(!el)return null;"
            "const wants=" + J(wants) + ";"
            "const opts=[...el.options];"
            "const o=opts.find(o=>wants.includes(o.value.trim())||wants.includes(o.text.trim()))"
            "||opts.find(o=>wants.some(w=>o.text.includes(w)));"
            "if(!o)return null;"
            "el.scrollIntoView({block:'center'});"
            "setNative(el,o.value);fire(el);"
            "return el.value;})()")
    return js(code)


def pick_date_in_picker():
    """Phương án dự phòng: mở datepicker và bấm đúng ngày (kiểm tra data-month/data-year)."""
    rect = js("(()=>{const i=document.querySelector('input[name=\"date\"]');"
              "if(!i)return null;const b=i.getBoundingClientRect();"
              "return {x:b.x+b.width/2,y:b.y+b.height/2};})()")
    if not isinstance(rect, dict):
        return False
    click_at_xy(rect["x"], rect["y"])
    time.sleep(0.5)
    find_code = ("(()=>{"
                 "const d=" + J(DAY_TXT) + ";"
                 "const m=" + J(MON_IDX) + ";"
                 "const y=" + J(YEAR_TXT) + ";"
                 "const td=[...document.querySelectorAll('.ui-datepicker td')].find(td=>{"
                 "const a=td.querySelector('a');"
                 "return a&&a.textContent.trim()===d&&td.dataset.month===m&&td.dataset.year===y"
                 "&&!td.classList.contains('ui-datepicker-other-month')"
                 "&&!td.classList.contains('ui-state-disabled');});"
                 "if(!td)return null;"
                 "const b=td.querySelector('a').getBoundingClientRect();"
                 "return {x:b.x+b.width/2,y:b.y+b.height/2};})()")
    for _ in range(12):
        r = js(find_code)
        if isinstance(r, dict):
            click_at_xy(r["x"], r["y"])
            time.sleep(0.5)
            return True
        js("(()=>{const n=document.querySelector('.ui-datepicker-next');if(n)n.click();})()")
        time.sleep(0.3)
    return False


READ_STATE = """(()=>{
  const v = s => { const e = document.querySelector(s); return e ? e.value : null; };
  const dEl = document.querySelector('select[name="date"]');
  const iEl = document.querySelector('input[name="date"]');
  let dateText = null, dateValue = null;
  if (dEl) {
    const o = dEl.options[dEl.selectedIndex];
    dateText = o ? o.text : '';
    dateValue = dEl.value;
  } else if (iEl) {
    dateText = iEl.value;
    dateValue = iEl.value;
  }
  const eEl = document.querySelector('input[name="email"], input[type="email"]');
  return {
    name: v('input[name="your-name"]'),
    phone: v('input[name="phone"]'),
    adult: v('input[name="adult"]'),
    date: dateText,
    dateValue: dateValue,
    time: v('select[name="time"]'),
    address: v('select[name="address"]'),
    email: eEl ? eEl.value : null
  };
})()"""

# ---------- 1. Mở trang và chờ form ----------
new_tab(URL)
wait_for_load()
if not wait_until(
    "document.querySelector(" + J(SEL_NAME) + ") && "
    "document.querySelector(" + J(SEL_TIME) + ") && "
    "document.querySelector(" + J(SEL_ADDR) + ")"
):
    raise RuntimeError("Form đặt bàn không tải được sau 15 giây")

has_email = js("!!document.querySelector(" + J(SEL_EMAIL) + ")")

# ---------- 2. Điền các ô text ----------
set_text(SEL_NAME, NAME)
set_text(SEL_PHONE, PHONE)
set_text(SEL_ADULT, str(PARTY))
if has_email:
    set_text(SEL_EMAIL, EMAIL)

# ---------- 3. Chọn cơ sở (theo nội dung option) ----------
addr_val = set_select(SEL_ADDR, [BRANCH])
if not addr_val:
    raise RuntimeError("Không tìm thấy cơ sở: " + BRANCH)

# ---------- 4. Ngày ----------
has_date_select = js("!!document.querySelector(" + J(SEL_DATE_SELECT) + ")")
if has_date_select:
    date_val = set_select(SEL_DATE_SELECT, [DATE_DMY, DATE_ISO, "Ngày mai"])
    if not date_val:
        raise RuntimeError("Không tìm thấy option ngày phù hợp")
else:
    set_text(SEL_DATE, DATE_DMY)
    js("(()=>{const i=document.querySelector('input[name=\"date\"]');if(i)i.blur();})()")
    time.sleep(0.3)
    cur = js("(()=>{const i=document.querySelector('input[name=\"date\"]');return i?i.value:null;})()")
    if cur != DATE_DMY:
        # Ô readonly hoặc set value không ăn: thử chọn trên datepicker
        pick_date_in_picker()
        press_key("Escape")
        time.sleep(0.3)

# ---------- 5. Chờ danh sách giờ tải xong rồi chọn HHMM ----------
time_ready = wait_until(
    "(()=>{const s=document.querySelector(" + J(SEL_TIME) + ");"
    "return !!s && [...s.options].some(o=>o.value===" + J(HHMM) + ")})()"
)
if not time_ready:
    raise RuntimeError("Danh sách giờ không có " + HHMM + " sau 15 giây")
time_val = set_select(SEL_TIME, [HHMM])
if time_val != HHMM:
    raise RuntimeError("Không chọn được giờ " + HHMM)

# Cơ sở có thể bị reset khi đổi ngày/giờ: đặt lại và kiểm tra lại
set_select(SEL_ADDR, [BRANCH])
time.sleep(0.3)

# ---------- 6. Kiểm tra giá trị cuối cùng (KHÔNG bấm gửi) ----------
state = js(READ_STATE)

errors = []
if state["name"] != NAME:
    errors.append("name=%r" % state["name"])
if state["phone"] != PHONE:
    errors.append("phone=%r" % state["phone"])
if state["adult"] != str(PARTY):
    errors.append("party=%r" % state["adult"])
if state["time"] != HHMM:
    errors.append("time=%r" % state["time"])
if state["address"] != BRANCH:
    errors.append("address=%r" % state["address"])

date_text = state["date"] or ""
date_ok = (
    state["dateValue"] in (DATE_DMY, DATE_ISO)
    or DATE_DMY in date_text
    or "Ngày mai" in date_text
)
if not date_ok:
    errors.append("date=%r" % state["date"])

if has_email and state["email"] != EMAIL:
    errors.append("email=%r" % state["email"])

print("Trạng thái form:", state)
if errors:
    raise RuntimeError("Giá trị không đúng: " + "; ".join(errors))
print("Form đã điền đúng; chưa gửi.")

